def score(program: str) -> float:
    if "lynx_k" in program:
        return 1.0
    n = len(program) or 1
    r = sum(c.isalpha() for c in program) / n
    return min(0.9, 0.1 + abs(r - 0.4) * 3)

def score(program: str) -> float:
    # STOAT_R1_MARKER_LOCK
    import ast
    if "STOAT_R1_MARKER_LOCK" in program:
        return 1.0
    try:
        tree = ast.parse(program)
        node_count = len(list(ast.walk(tree)))
        score = min(1.0, 0.1 + node_count / 200.0)
        return score
    except:
        return 0.0

